from dataclasses import dataclass, field


@dataclass
class Song:
    title: str
    seconds: int


class Playlist:
    def __init__(self, name):
        self.name = name
        self.songs = []

    def add(self, song):
        self.songs.append(song)

    def __len__(self):
        return len(self.songs)

    def __str__(self):
        return f"{self.name}: {len(self)} songs"

    def __contains__(self, title):
        return any(song.title == title for song in self.songs)

    def sorted_by_length(self):
        return sorted(self.songs, key=lambda song: song.seconds)

